const directoryURL=p=>{const u=new URL(p,assetModuleURL);if(!u.pathname.endsWith('/'))u.pathname+='/';return u};
const assetModuleURL=import.meta.url;
import{scope,loadPlayers,visibleView}from'./common.mjs';import{MAPS,prepareS4TargetSupport,borrowSupport}from'./support.mjs';import{createS4TargetRenderer}from'./target-renderer.mjs';import{TARGET_PINS_SHA}from'../gohyeon-pair/target-pins.mjs';import{DEPTH_SELECTION_SHA}from'../gohyeon-pair/selected_depth/depth-pins.mjs';import{NPC_ART}from'../gohyeon-gameplay/selected-npc-art.mjs';
const pair=directoryURL('../gohyeon-pair/'),game=directoryURL('../gohyeon-gameplay/'),json=b=>JSON.parse(new TextDecoder().decode(b));
export async function prepareS4AreaPresentation(options={}){const{mapId,appearance='boy',canvasFactory=(w,h)=>new OffscreenCanvas(w,h)}=options;if(![MAPS.park,MAPS.greenbelt].includes(mapId)||!['boy','girl'].includes(appearance))throw Error('S4_AREA_SELECTION');const td=Object.getOwnPropertyDescriptor(options,'supportLeaseToken');if(td&&(!td.enumerable||!Object.hasOwn(td,'value'))||!td&&'supportLeaseToken'in options)throw Error('S4_SUPPORT_TOKEN_DESCRIPTOR');const s=scope(options),canvases=[],make=(w,h)=>{s.check();const c=canvasFactory(w,h);canvases.push(c);return c};let support,renderer;s.onCleanup(()=>{renderer=null});s.onCleanup(()=>support?.dispose());s.onCleanup(()=>{for(const c of canvases)try{c.width=c.height=1}catch{}canvases.length=0});try{s.check();support=td?.value==null?await prepareS4TargetSupport(options):borrowSupport(td.value,mapId);s.check();const pins=json(await s.pinned(new URL('TARGET_INPUT_PINS.json',pair),TARGET_PINS_SHA)),read=async k=>{const p=pins[k];if(!p)throw Error('S4_UNPINNED_AREA');return s.pinned(new URL(p.path,pair),p.sha256,p.bytes)},typed=async(k,T)=>{const b=await read(k);if(b.byteLength%T.BYTES_PER_ELEMENT)throw Error('S4_TYPED_ALIGNMENT');return new T(b.buffer,b.byteOffset,b.byteLength/T.BYTES_PER_ELEMENT)},park=mapId===MAPS.park,k=park?'park':'green',input={manifest:json(await read(k+'Manifest')),image:await s.image(await read(k+'Image'),1536,1024)};
if(park){input.ids=await typed('parkLightIds',Uint32Array);input.transmission=await typed('parkLightTransmission',Float64Array)}else{input.layers=[{ids:await typed('greenWaterIds',Uint32Array),rgb:await read('greenWaterRGB')},{ids:await typed('greenLeafIds',Uint32Array),rgb:await read('greenLeafRGB')}];input.light={ids:await typed('greenLightIds',Uint32Array),trans:await typed('greenLightTransmission',Float64Array)}}
const actors=await loadPlayers(s,appearance,make),depthBase=new URL('selected_depth/',pair),selection=json(await s.pinned(new URL('ROOT_DEPTH_SELECTION.json',depthBase),DEPTH_SELECTION_SHA)),foregroundLayers=[];for(const l of selection.layers.filter(l=>l.mapId===mapId)){const mask=await s.pinned(new URL(l.maskPath,depthBase),l.maskSHA,l.size[0]*l.size[1]);foregroundLayers.push({...l,mask})}const sprites=[];if(!park)for(const row of NPC_ART){const b=await s.pinned(new URL(row.path,game),row.sha256,row.bytes),image=await s.image(b,row.width,row.height);sprites.push({row,image})}const npcs={sprites:()=>sprites};renderer=createS4TargetRenderer({inputs:{[k]:input},actors,scratchFactory:make,foregroundLayers,npcs,targetMapId:mapId});s.check();return visibleView({s,support,appearance,make,drawNative:(ctx,v)=>renderer(ctx,{...v.pose,walking:v.walking},v.clock)})}catch(e){s.dispose();throw e}}
